package com.eurobuddha.pandapools;

import static org.junit.Assert.*;

import android.content.Context;
import android.net.Uri;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;

import java.io.File;

/** Generated by scripts/adapt-pandamonium-dexicon.py: the in-process node's backup path is accepted only inside our files. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk = 34)
public class NodeBackupOwnFileTest {
    @Test public void onlyOurOwnFilesFolder() throws Exception {
        Context c = RuntimeEnvironment.getApplication();
        File mine = new File(c.getFilesDir(), "pp-backup-1.bak");
        assertTrue(NodeBackupCapture.ownFile(c, Uri.fromFile(mine)));
        assertFalse("outside the folder", NodeBackupCapture.ownFile(c, Uri.fromFile(new File("/sdcard/Download/x.bak"))));
        assertFalse("no escaping with ..", NodeBackupCapture.ownFile(c, Uri.fromFile(new File(c.getFilesDir(), "../shared_prefs/x.xml"))));
        assertFalse("content is the IPC path, handled before", NodeBackupCapture.ownFile(c, Uri.parse("content://x/y")));
    }
}
